6289:             }
6290:             # (wave 24) when the failure happened - a time in the future counts as now (F15-4) -
6291:             # and, without a reset time, the 60 minutes it stays out ((wave 24c) 10 for a burst)
6292:             $hit = $reference
6293:             if ($hit.UtcDateTime -gt $UtcNow) { $hit = $nowOffset.ToOffset($hit.Offset) }
6294:             $rec.Hit = $hit
6295:             $rec.HitIso = Format-OffsetIso $hit
6296:             $rec.Until = $hit.AddMinutes($rec.OutMinutes)
6297:             if ($null -ne $rec.RetryAfter) {
6298:                 $rec.RetryAfterIso = Format-OffsetIso $rec.RetryAfter
6299:                 $rec.Until = $rec.RetryAfter
6300:             }
6301:             # (wave 26c, D2 / F26-2) a machine-wide record's stored until (never in a ledger's
